import { create } from 'zustand';
import { createJSONStorage, persist } from 'zustand/middleware';

/* ==========================================================================
 * Portfolio content store.
 *
 * Holds the editable content of the journey (profile, education, companies,
 * projects, skills, contact). It is a reactive Zustand store persisted to
 * localStorage. Scroll-driven values never live here — see scrollStore.ts.
 * ========================================================================== */

export type TechCategory =
  | 'language'
  | 'frontend'
  | 'backend'
  | 'data'
  | 'devops'
  | 'cloud'
  | 'tooling';

export interface TechLogo {
  /** Simple Icons slug. */
  slug: string;
  name: string;
  /** Official brand hex colour (uppercase, with leading #). */
  hex: string;
  category: TechCategory;
  /** Official 24×24 SVG path data (viewBox "0 0 24 24"). */
  path: string;
}

export interface Trait {
  id: string;
  label: string;
  value: string;
}

export interface Profile {
  name: string;
  headline: string;
  location: string;
  summary: string;
  welcomeMessage: string;
  horizonMessage: string;
  traits: Trait[];
}

export interface EducationEntry {
  id: string;
  institution: string;
  degree: string;
  field: string;
  startYear: number;
  endYear: number | null;
  highlights: string[];
}

export interface BasicSkill {
  id: string;
  label: string;
  /** 0 → 1 proficiency used to scale HUD bars. */
  level: number;
}

export interface Company {
  id: string;
  /** Which ascent scene (1-3) this company is shown in. */
  stage: 1 | 2 | 3;
  name: string;
  role: string;
  location: string;
  startDate: string;
  endDate: string | null;
  summary: string;
  achievements: string[];
  techSlugs: string[];
}

export interface Project {
  id: string;
  /** Which ascent beacon (1-3) this project is pinned to. */
  stage: 1 | 2 | 3;
  companyId: string | null;
  title: string;
  tagline: string;
  description: string;
  impact: string[];
  techSlugs: string[];
  url: string | null;
  repoUrl: string | null;
}

export interface SkillRef {
  slug: string;
  /** 0 → 1 proficiency, drives orbit radius / glow at the summit. */
  level: number;
  years: number;
}

export interface ContactLink {
  id: string;
  label: string;
  href: string;
  handle: string;
}

export interface ContactDetails {
  email: string;
  phone: string | null;
  location: string;
  availability: string;
  resumeUrl: string | null;
  links: ContactLink[];
}

export interface PortfolioData {
  profile: Profile;
  education: EducationEntry[];
  basicSkills: BasicSkill[];
  companies: Company[];
  projects: Project[];
  skills: SkillRef[];
  contact: ContactDetails;
}

export interface PortfolioActions {
  setProfile: (patch: Partial<Profile>) => void;
  setTraits: (traits: Trait[]) => void;
  upsertEducation: (entry: EducationEntry) => void;
  removeEducation: (id: string) => void;
  setBasicSkills: (skills: BasicSkill[]) => void;
  upsertCompany: (company: Company) => void;
  updateCompany: (id: string, patch: Partial<Omit<Company, 'id'>>) => void;
  removeCompany: (id: string) => void;
  upsertProject: (project: Project) => void;
  updateProject: (id: string, patch: Partial<Omit<Project, 'id'>>) => void;
  removeProject: (id: string) => void;
  setSkills: (skills: SkillRef[]) => void;
  setContact: (patch: Partial<ContactDetails>) => void;
  importData: (data: unknown) => boolean;
  exportData: () => string;
  resetToDefaults: () => void;
}

export type PortfolioState = PortfolioData & PortfolioActions;

