export type TechSlug = keyof typeof OFFICIAL_TECH_LOGOS;

export const TECH_SLUGS = Object.keys(OFFICIAL_TECH_LOGOS) as TechSlug[];

export function isTechSlug(slug: string): slug is TechSlug {
  return Object.prototype.hasOwnProperty.call(OFFICIAL_TECH_LOGOS, slug);
}

export function getTechLogo(slug: string): TechLogo | null {
  return isTechSlug(slug) ? OFFICIAL_TECH_LOGOS[slug] : null;
}

/**
 * Several official brand colours are black or near-black and disappear on
 * the #040508 canvas. This returns the official colour unless its relative
 * luminance is too low, in which case a neutral light tint is used.
 */
export function displayHex(hex: string): string {
  const value = hex.replace('#', '');
  if (value.length !== 6) return '#E6EDF6';
  const channel = (offset: number): number => {
    const c = parseInt(value.slice(offset, offset + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  };
  const luminance = 0.2126 * channel(0) + 0.7152 * channel(2) + 0.0722 * channel(4);
  return luminance < 0.06 ? '#E6EDF6' : `#${value.toUpperCase()}`;
}

/** Full standalone SVG markup for a logo, usable as an <img> data URI or texture. */
export function techLogoSvg(slug: string, color?: string): string | null {
  const logo = getTechLogo(slug);
  if (!logo) return null;
  const fill = color ?? displayHex(logo.hex);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" role="img" aria-label="${logo.name}"><path fill="${fill}" d="${logo.path}"/></svg>`;
}

