/* ---------------------------------------------------------------------------
 * Validation for imported JSON
 * ------------------------------------------------------------------------- */

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function isPortfolioData(value: unknown): value is PortfolioData {
  if (!isRecord(value)) return false;
  const { profile, education, basicSkills, companies, projects, skills, contact } = value;
  return (
    isRecord(profile) &&
    typeof profile.name === 'string' &&
    Array.isArray(profile.traits) &&
    Array.isArray(education) &&
    Array.isArray(basicSkills) &&
    Array.isArray(companies) &&
    companies.every((c) => isRecord(c) && typeof c.id === 'string' && typeof c.name === 'string') &&
    Array.isArray(projects) &&
    projects.every((p) => isRecord(p) && typeof p.id === 'string' && typeof p.title === 'string') &&
    Array.isArray(skills) &&
    skills.every((s) => isRecord(s) && typeof s.slug === 'string') &&
    isRecord(contact) &&
    typeof contact.email === 'string' &&
    Array.isArray(contact.links)
  );
}

const cloneDefaults = (): PortfolioData => structuredClone(DEFAULT_PORTFOLIO);

function upsertById<T extends { id: string }>(list: T[], item: T): T[] {
  const index = list.findIndex((entry) => entry.id === item.id);
  if (index === -1) return [...list, item];
  const next = list.slice();
  next[index] = item;
  return next;
}

const PORTFOLIO_STORAGE_KEY = 'gokul-mv.portfolio';
const PORTFOLIO_STORAGE_VERSION = 1;

const pickData = (state: PortfolioState): PortfolioData => ({
  profile: state.profile,
  education: state.education,
  basicSkills: state.basicSkills,
  companies: state.companies,
  projects: state.projects,
  skills: state.skills,
  contact: state.contact,
});

export const usePortfolioStore = create<PortfolioState>()(
  persist(
    (set, get) => ({
      ...cloneDefaults(),

      setProfile: (patch) => set((s) => ({ profile: { ...s.profile, ...patch } })),
      setTraits: (traits) => set((s) => ({ profile: { ...s.profile, traits } })),

      upsertEducation: (entry) => set((s) => ({ education: upsertById(s.education, entry) })),
      removeEducation: (id) => set((s) => ({ education: s.education.filter((e) => e.id !== id) })),

      setBasicSkills: (basicSkills) => set({ basicSkills }),

      upsertCompany: (company) => set((s) => ({ companies: upsertById(s.companies, company) })),
      updateCompany: (id, patch) =>
        set((s) => ({ companies: s.companies.map((c) => (c.id === id ? { ...c, ...patch } : c)) })),
      removeCompany: (id) =>
        set((s) => ({
          companies: s.companies.filter((c) => c.id !== id),
          projects: s.projects.map((p) => (p.companyId === id ? { ...p, companyId: null } : p)),
        })),

      upsertProject: (project) => set((s) => ({ projects: upsertById(s.projects, project) })),
      updateProject: (id, patch) =>
        set((s) => ({ projects: s.projects.map((p) => (p.id === id ? { ...p, ...patch } : p)) })),
      removeProject: (id) => set((s) => ({ projects: s.projects.filter((p) => p.id !== id) })),

      setSkills: (skills) => set({ skills: skills.filter((skill) => isTechSlug(skill.slug)) }),

      setContact: (patch) => set((s) => ({ contact: { ...s.contact, ...patch } })),

      importData: (data) => {
        let parsed: unknown = data;
        if (typeof data === 'string') {
          try {
            parsed = JSON.parse(data);
          } catch {
            return false;
          }
        }
        if (!isPortfolioData(parsed)) return false;
        set({
          ...parsed,
          skills: parsed.skills.filter((skill) => isTechSlug(skill.slug)),
        });
        return true;
      },

      exportData: () => JSON.stringify(pickData(get()), null, 2),

      resetToDefaults: () => set(cloneDefaults()),
    }),
    {
      name: PORTFOLIO_STORAGE_KEY,
      version: PORTFOLIO_STORAGE_VERSION,
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => pickData(state),
      migrate: (persisted) => (isPortfolioData(persisted) ? persisted : cloneDefaults()) as PortfolioState,
    },
  ),
);

/* ---------------------------------------------------------------------------
 * Non-reactive selectors (safe to call from rAF / useFrame)
 * ------------------------------------------------------------------------- */

export const getPortfolio = (): PortfolioState => usePortfolioStore.getState();

export const getCompanyForStage = (stage: 1 | 2 | 3): Company | undefined =>
  usePortfolioStore.getState().companies.find((c) => c.stage === stage);

export const getProjectForStage = (stage: 1 | 2 | 3): Project | undefined =>
  usePortfolioStore.getState().projects.find((p) => p.stage === stage);
